Definition CH : nat := Z.to_nat 65536.
Definition chunk (j : nat) (c : list byte) : list byte := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S10!1+^Q!1,^P|30;$j;R+_N$c;R!1+N0!3'_O0'_P!3'_Q0!2'_R'_P#2#1").
