Lemma fact_sound : forall E cs R FULL model K,
  cs_ok E cs R FULL model -> fact_ok (kn cs) K = true -> cs_ok E (add_kn cs [K]) R FULL model.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S60!1+^Q!1,^P|600;|30;!3,B+cF#3!1,M+cF!1'bP#7!4'bL#8#7#4#5!6'cP#8#7#6#5#4#2$E;R+^[$cs;R+_:$R;R!2'^O!1,^P|21;0$FULL;R%~R0!1+^R!1+^Q!1,^P1$model;R+^S$K;R+cF$HC;R!5+a7#6#5#4#3#2$H;R!3+:+^;!2'lU!1'bP#6#2,^<vd!8'cN#8#7#6#5#4!3'_<+cF23#2!6,fI+cF!3'cG/SEGS;#84#33!6'm0#843#35#15!5+a7#8!2'm1#72#6#5#4").
Qed.

Lemma regs_ok_ext_eq : forall E sr sr' R, sr = sr' -> regs_ok E sr R -> regs_ok E sr' R.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S10!1+N+_6$E;R+^[$sr;R0$sr';R0$R;R!2'^O!1,^P|21;!1+^Q!1,^P|600;$~R!3+:0#3#2$~R!3'bG#5#4#2!7'^B0#4$sr;R0%H0;R!3'bG#7#1#4!3'bG#8#6#5$H0;R!3'bG#6#4#3#1#5#2#1").
Qed.

(* [comment removed for export] *)
