Lemma pc_inst : forall inv J e, pc (inst inv J e) = pc inv.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$inv;R+_:$J;R+_N$e;R+_6!2,^:+0!1'd4#3").
Qed.
Lemma nxt_inst : forall inv J e, nxt (inst inv J e) = nxt inv.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$inv;R+_:$J;R+_N$e;R+_6!2,^:+_N!1'f\#3").
Qed.

