  Lemma uE_rename : forall E e, evars_all (ren_ok fw bw) e = true -> uE (ren_env bw E) (erename fw e) = uE E e.
  Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S50!1,^P|600;!1+^Q0!2'_A#3#2!2'^]A/bw;#3!2'^]>/fw;#2$E;R+^[$e;R+_6$~R!3+:+^;!2'^];!2'^]C/fw;/bw;#1,^<vd!6'^B12$b;R1!3+:+0!2'`@0#1!2'`@0!2'_A#4#3!2,^:+0!2'`@02!2'_A34!3/ER;#3#2#1!3+:+0!2'_734!2'_7#3#2").
