Definition lc_guard (lc : option loopctx) (cs : acs) : bool := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$lc;R!1+^R+s3$cs;R+_:-^RRN$lc;R!1+^R+s3+^;#22$c;R+s3!2'e=!1's5#1!1'f\#2,^<").

